input.sparql:
SELECT ?zone ?point ?tsid WHERE {
  ?zone brick:hasSubgraph | a brick:Zone .
  FILTER(str(?zone) LIKE "%Perimeter_bot_ZN_2%")
}
LIMIT 10

SELECT ?z ?label ?p WHERE {
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_bot_ZN_2"))
  OPTIONAL { ?z ?p ?o . FILTER(?p = brick:hasPoint) }
}
LIMIT 20

SELECT ?point ?tclass ?tsid WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_2" .
  ?z brick:hasPoint ?point .
  ?point a ?tclass .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
}

SELECT ?point ?tsref WHERE {
  ?point a brick:Occupancy_Sensor .
  ?point ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?tsid .
  FILTER(CONTAINS(str(?point), "Zone_F1_Z03"))
}
